**3. Integrate a secrets manager for production:**

```javascript
// secrets.js - AWS Secrets Manager example
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: 'us-east-1' });

async function getSecrets(secretName) {
  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await client.send(command);
    return JSON.parse(response.SecretString);
  } catch (error) {
    console.error('Failed to retrieve secrets:', error.message);
    throw error;
  }
}

// Usage in app initialization
async function initializeApp() {
  const secrets = await getSecrets('my-app/production');

  // Now configure your services with secrets
  // Don't store in process.env - keep in memory only
  return {
    dbUrl: secrets.DATABASE_URL,
    stripeKey: secrets.STRIPE_SECRET_KEY,
  };
}

module.exports = { getSecrets, initializeApp };
```

**4. Environment-aware configuration pattern:**

```javascript
// config.js
const loadSecrets = async () => {
  if (process.env.NODE_ENV === 'production') {
    // Use secrets manager in production
    const { getSecrets } = require('./secrets');
    return getSecrets('my-app/production');
  } else {
    // Only use dotenv in development
    require('dotenv').config();
    return {
      DATABASE_URL: process.env.DATABASE_URL,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      // ... etc
    };
  }
};

module.exports = { loadSecrets };
```

