### Option 1: AWS Secrets Manager (Recommended for AWS)

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

const secretsCache = {};

async function getSecret(secretName) {
  if (secretsCache[secretName]) {
    return secretsCache[secretName];
  }

  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await client.send(command);

    const secret = response.SecretString 
      ? JSON.parse(response.SecretString)
      : Buffer.from(response.SecretBinary, 'base64').toString();

    secretsCache[secretName] = secret;
    return secret;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error.message);
    throw error;
  }
}

// Usage
async function initializeApp() {
  const dbSecrets = await getSecret('myapp/production/database');
  const apiKeys = await getSecret('myapp/production/api-keys');

  return {
    databaseUrl: dbSecrets.DATABASE_URL,
    stripeKey: apiKeys.STRIPE_SECRET_KEY,
    anthropicKey: apiKeys.ANTHROPIC_API_KEY
  };
}

module.exports = { getSecret, initializeApp };
