// config/env.js
'use strict';

const requiredEnvVars = [
  'DATABASE_URL',
  'JWT_SECRET',
  'NODE_ENV'
];

const sensitiveEnvVars = [
  'DATABASE_URL',
  'AWS_SECRET_ACCESS_KEY',
  'STRIPE_SECRET_KEY',
  'ANTHROPIC_API_KEY',
  'JWT_SECRET'
];

function validateEnv() {
  const missing = requiredEnvVars.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  // Validate format where possible
  if (process.env.DATABASE_URL && !process.env.DATABASE_URL.startsWith('postgres://')) {
    throw new Error('DATABASE_URL must be a valid PostgreSQL connection string');
  }

  // Warn about development values in production
  if (process.env.NODE_ENV === 'production') {
    if (process.env.JWT_SECRET === 'development-secret') {
      throw new Error('Cannot use development JWT secret in production');
    }
    if (process.env.STRIPE_SECRET_KEY?.includes('test')) {
      console.warn('WARNING: Using test Stripe key in production environment');
    }
  }
}

// Prevent secrets from being logged
function getSafeEnvForLogging() {
  const safeEnv = { ...process.env };
  sensitiveEnvVars.forEach(key => {
    if (safeEnv[key]) {
      safeEnv[key] = '[REDACTED]';
    }
  });
  return safeEnv;
}

// Freeze config to prevent runtime modification
function getConfig() {
  validateEnv();

  return Object.freeze({
    nodeEnv: process.env.NODE_ENV,
    port: parseInt(process.env.PORT, 10) || 3000,
    database: {
      url: process.env.DATABASE_URL,
      poolSize: parseInt(process.env.DB_POOL_SIZE, 10) || 10
    },
    jwt: {
      secret: process.env.JWT_SECRET,
      expiresIn: process.env.JWT_EXPIRES_IN || '1h'
    },
    // Add other non-sensitive config
  });
}

module.exports = { validateEnv, getSafeEnvForLogging, getConfig };
