  STRIPE_SECRET_KEY: Joi.string().pattern(/^sk_(test|live)_/).required(),
  LOGFIRE_TOKEN: Joi.string().required(),
}).unknown();

function loadConfig() {
  // Only load dotenv in development
  if (process.env.NODE_ENV !== 'production') {
    require('dotenv').config();
  }

  const { error, value } = envSchema.validate(process.env);

  if (error) {
    console.error('Configuration validation error:', error.message);
    process.exit(1);
  }

  // Warn if using test keys in production
  if (value.NODE_ENV === 'production') {
    if (value.STRIPE_SECRET_KEY.startsWith('sk_test_')) {
      console.warn('WARNING: Using Stripe test key in production!');
    }
  }

  return Object.freeze({
    env: value.NODE_ENV,
    database: {
      url: value.DATABASE_URL,
    },
    aws: {
      accessKeyId: value.AWS_ACCESS_KEY_ID,
      secretAccessKey: value.AWS_SECRET_ACCESS_KEY,
    },
    anthropic: {
      apiKey: value.ANTHROPIC_API_KEY,
    },
    stripe: {
      secretKey: value.STRIPE_SECRET_KEY,
    },
    logfire: {
      token: value.LOGFIRE_TOKEN,
    },
  });
}

module.exports = loadConfig();
```

