## Recommended Secrets Management Architecture

### Option 1: AWS Secrets Manager (Recommended for AWS environments)

```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);
      const secret = JSON.parse(response.SecretString);

      this.cache.set(secretName, { value: secret, timestamp: Date.now() });
      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error('Failed to retrieve secret');
    }
  }
}

// Usage
const secrets = new SecretsManager();

async function initializeApp() {
  const dbSecrets = await secrets.getSecret('myapp/production/database');
  const apiKeys = await secrets.getSecret('myapp/production/api-keys');

  return {
    databaseUrl: `postgres://${dbSecrets.username}:${dbSecrets.password}@${dbSecrets.host}:5432/${dbSecrets.database}`,
    stripeKey: apiKeys.stripe,
    anthropicKey: apiKeys.anthropic
  };
}
```

