const Joi = require('joi');

const envSchema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'staging', 'production').required(),
  PORT: Joi.number().default(3000),

  // Database
  DATABASE_URL: Joi.string().uri({ scheme: ['postgres', 'postgresql'] }).required(),

  // AWS (only require in production)
  AWS_ACCESS_KEY_ID: Joi.string().pattern(/^AKIA[A-Z0-9]{16}$/).when('NODE_ENV', {
    is: 'production',
    then: Joi.required()
  }),
  AWS_SECRET_ACCESS_KEY: Joi.string().min(40).when('NODE_ENV', {
    is: 'production',
    then: Joi.required()
  }),

  // API Keys
  ANTHROPIC_API_KEY: Joi.string().pattern(/^sk-ant-/).required(),
  STRIPE_SECRET_KEY: Joi.string().pattern(/^sk_(live|test)_/).required(),
  LOGFIRE_TOKEN: Joi.string().required()
}).unknown();

function validateEnv() {
  const { error, value } = envSchema.validate(process.env, { abortEarly: false });

  if (error) {
    console.error('Environment validation failed:');
    error.details.forEach(detail => {
      console.error(`  - ${detail.message}`);
    });
    process.exit(1);
  }

  // Warn if using test keys in production
  if (value.NODE_ENV === 'production') {
    if (value.STRIPE_SECRET_KEY?.includes('_test_')) {
      console.warn('WARNING: Using Stripe test key in production!');
    }
  }

  return value;
}

const config = validateEnv();
module.exports = config;
```

