### 3. **Create a Secure Configuration Module**

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.secrets = null;
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });
  }

  async initialize() {
    if (process.env.NODE_ENV === 'development') {
      // Only allow .env in development, with warning
      console.warn('⚠️  Loading secrets from environment variables (development only)');
      this.secrets = {
        databaseUrl: process.env.DATABASE_URL,
        stripeKey: process.env.STRIPE_SECRET_KEY,
        anthropicKey: process.env.ANTHROPIC_API_KEY,
      };
      return;
    }

    // Production: use secrets manager
    const response = await this.client.send(
      new GetSecretValueCommand({ 
        SecretId: `${process.env.NODE_ENV}/app/secrets` 
      })
    );
    this.secrets = JSON.parse(response.SecretString);
  }

  get(key) {
    if (!this.secrets) {
      throw new Error('Secrets not initialized. Call initialize() first.');
    }
    const value = this.secrets[key];
    if (!value) {
      throw new Error(`Secret '${key}' not found`);
    }
    return value;
  }
}

module.exports = new SecretsManager();
```

### 4. **Sanitize Logging to Prevent Secret Leakage**

```javascript
// utils/logger.js
const sensitivePatterns = [
  /sk_live_[a-zA-Z0-9]+/g,           // Stripe keys
  /sk-ant-[a-zA-Z0-9-]+/g,           // Anthropic keys
  /AKIA[A-Z0-9]{16}/g,               // AWS access keys
  /postgres:\/\/[^@]+@/g,            // Database URLs with creds
  /Bearer\s+[a-zA-Z0-9._-]+/gi,      // Bearer tokens
];

function sanitize(message) {
  let sanitized = String(message);
  for (const pattern of sensitivePatterns) {
    sanitized = sanitized.replace(pattern, '[REDACTED]');
  }
  return sanitized;
}

function secureLog(level, message, meta = {}) {
  const sanitizedMessage = sanitize(message);
  const sanitizedMeta = JSON.parse(sanitize(JSON.stringify(meta)));

  console[level](sanitizedMessage, sanitizedMeta);
}

module.exports = {
  info: (msg, meta) => secureLog('info', msg, meta),
  error: (msg, meta) => secureLog('error', msg, meta),
  warn: (msg, meta) => secureLog('warn', msg, meta),
};
```

